 1→import { readFileSync, existsSync } from 'node:fs';
 2→import { resolve } from 'node:path';
 3→
 4→describe('Fretboard SVG asset', () => {
 5→  const svgPath = resolve(__dirname, '../../../../public/images/fretboard.svg');
 6→  let svgContent: string;
 7→
 8→  beforeAll(() => {
 9→    svgContent = existsSync(svgPath) ? readFileSync(svgPath, 'utf-8') : '';
10→  });
11→
12→  it('should exist as a file in the public assets directory', () => {
13→    expect(existsSync(svgPath)).toBe(true);
14→  });
15→
16→  it('should be a valid SVG document', () => {
17→    expect(svgContent).toContain('<svg');
18→    expect(svgContent).toContain('xmlns="http://www.w3.org/2000/svg"');
19→    expect(svgContent).toContain('</svg>');
20→  });
21→
22→  it('should contain 6 strings represented as horizontal lines', () => {
23→    const stringLines = svgContent.match(/<line[^>]*class="string"[^>]*\/?>/g);
24→    expect(stringLines).not.toBeNull();
25→    expect(stringLines!.length).toBe(6);
26→  });
27→
28→  it('should contain the nut and 15 fret lines', () => {
29→    const fretLines = svgContent.match(/<line[^>]*class="fret"[^>]*\/?>/g);
30→    const nutLine = svgContent.match(/<line[^>]*class="nut"[^>]*\/?>/g);
31→    expect(nutLine).not.toBeNull();
32→    expect(nutLine!.length).toBe(1);
33→    expect(fretLines).not.toBeNull();
34→    expect(fretLines!.length).toBe(15);
35→  });
36→
37→  it('should contain single fret markers at positions 3, 5, 7, 9, 15', () => {
38→    const singleMarkers = svgContent.match(/<circle[^>]*class="fret-marker"[^>]*\/?>/g);
39→    expect(singleMarkers).not.toBeNull();
40→    expect(singleMarkers!.length).toBe(5);
41→  });
42→
43→  it('should contain a double fret marker at position 12', () => {
44→    const doubleMarkers = svgContent.match(/<circle[^>]*class="fret-marker-double"[^>]*\/?>/g);
45→    expect(doubleMarkers).not.toBeNull();
46→    expect(doubleMarkers!.length).toBe(2);
47→  });
48→
49→  it('should use a viewBox for scalable rendering', () => {
50→    const viewBoxMatch = svgContent.match(/viewBox="([^"]*)"/);
51→    expect(viewBoxMatch).not.toBeNull();
52→  });
53→});
